// The browse index wiring (browse-scale 3.5): the composition root's
// cmd-built closure set over the internal/browse Service — every store read
// and the naming composition arrive here, keeping browse a pure leaf (D2:
// it imports nothing internal) and api free of browse imports (INV2: the
// serve closures ride api.Deps as primitive-typed func fields).
//
// One walk covers the whole media corpus (photo libraries — the image
// module's libraries — are excluded v1, OQ1): per library ONE series read
// feeds both the namer's series-by-path join and the walk itself, and items
// arrive paged (the previewBatch precedent). Per row the title overrides are
// point-read through the same per-row posture the api DTO seam prices
// (display-naming D-9), memoized per walk — the corpus is a snapshot, so a
// row's override is read at most once per pass either way. Every failure is
// log-and-skip: a dropped row (or library) degrades recall, never lies —
// the honesty backstop (D3) composes every served byte live api-side. A
// whole-walk failure floors to an empty corpus (the service's nil-Corpus
// floor — the index rebuilds on the next drift trip or tick).
//
// The search entries compose through naming.Namer exactly as the DTO seam
// composes at request time: the composed served name is the top match tier
// and the precedence chain's LOSING names ride as the alternates (other
// languages, parser title, dir-name floor, segment floor) — a ru-pref module
// composing «Ария» must not make "aria" a miss (D2). The walk runs
// System-side (mute-blind — the shared/full index posture, D2): the only
// ResolveGates site that runs under a request's Viewer is api's
// ModulePresentation closure, and the bare ctx this wiring hands it is the
// zero-Viewer floor its chain-mute loop already degenerates on.
//
// The epoch rides ONE scalar control read over the naming-config horizon's
// three timestamped tables (title_overrides, metadata_source_prefs,
// modules). Library rows carry no updated_at column — schema truth — so a
// naming-knob PATCH converges only when a write it accompanies trips
// another leg; the design's ≤60 s recall bound holds for every write the
// schema timestamps. The SQL-over-store-DB posture here is the
// internal/identity precedent: a domain service constructed in cmd that
// reads Store.DB() directly.

package main

import (
	"context"
	"database/sql"
	"encoding/json"
	"errors"
	"fmt"
	"log/slog"
	"strconv"
	"strings"
	"sync"
	"time"

	"github.com/mellifera/mellifera/internal/access"
	"github.com/mellifera/mellifera/internal/api"
	"github.com/mellifera/mellifera/internal/browse"
	"github.com/mellifera/mellifera/internal/module"
	"github.com/mellifera/mellifera/internal/naming"
	"github.com/mellifera/mellifera/internal/store"
)

// browseInterval is the search-index task's ticker period (browse-scale D4,
// OQ4 — 60 s, locked like sweepInterval/recsInterval: a rule constant, not a
// knob). The janitor's interval<=0 law is the task's off position; no
// separate warm flag exists (OQ4) — disabling the task disables the boot
// warm with it, and serving floors to the never-built empty index.
const browseInterval = 60 * time.Second

// browseWalkBatch is the paged item walk width (the previewBatch precedent):
// one QueryItems page per iteration, id-ordered, so the corpus walk never
// materializes a whole library's item set at once.
const browseWalkBatch = 1000

// browseEpochSQL is the naming-config horizon's ONE scalar read (D4): the
// max updated_at across the three timestamped control tables a naming-config
// write touches — title overrides, source-gate prefs, module configs — plus
// the corpus row count (the leg that trips on adds AND deletes: a delete
// bumps no timestamp, Q3). Content rows feed NEITHER leg by contract: their
// changes arrive through the watermark walk (enrichment merges) and the
// scan-complete poke (scans), not through drift.
const browseEpochSQL = `
SELECT COALESCE(MAX(t.stamp), ''),
       (SELECT COUNT(*) FROM items  WHERE status <> 'deleted') +
       (SELECT COUNT(*) FROM series WHERE status <> 'deleted')
FROM (
  SELECT MAX(updated_at) AS stamp FROM title_overrides
  UNION ALL SELECT MAX(updated_at) FROM metadata_source_prefs
  UNION ALL SELECT MAX(updated_at) FROM modules
) t`

// browseWiring is the composition root's browse bundle: the service's Deps
// and the api serve closure that resolves facet-filter id sets — built
// together because both ride the SAME composer (the same pass-built
// resolver), so a filter's id sets can never diverge from the aggregates
// the facet chips serve.
type browseWiring struct {
	Deps browse.Deps
	// FacetIDs is the api Deps.FacetIDs closure (library-facets delta): the
	// whole-library scan over the naming resolver — the design-budgeted cost,
	// paid only when a facet filter is actually requested.
	FacetIDs func(ctx context.Context, libraryID int64, genre, kind, status string) (seriesIDs, itemIDs map[string]bool, err error)
}

// newBrowseWiring builds the browse closure set over the store, the module
// registry, and the presentation closure (the SAME closure api.Deps carries
// — one construction, both consumers, so the composer's title walk and the
// served presentation can never resolve gates differently).
func newBrowseWiring(
	st *store.Store, reg *module.Registry,
	modulePres func(context.Context, string, int64) (api.ModulePresentation, error),
) browseWiring {
	c := &browseComposer{
		st:         st,
		reg:        reg,
		modulePres: modulePres,
		namers:     map[string]naming.Namer{},
	}
	return browseWiring{
		Deps: browse.Deps{
			Epoch:     c.epoch,
			Corpus:    c.corpus,
			Changed:   c.changed,
			LiveIDs:   c.liveIDs,
			Resolver:  c.resolver,
			FacetDocs: c.facetDocs,
		},
		FacetIDs: c.facetIDs,
	}
}

// browseComposer is the cmd-built closure set behind browse.Deps and the
// api serve closures: the store, the module registry, the presentation
// closure, and the per-pass namer cache the Resolver resolves through.
type browseComposer struct {
	st         *store.Store
	reg        *module.Registry
	modulePres func(context.Context, string, int64) (api.ModulePresentation, error)

	// namers caches the per-library namer the Resolver resolves through,
	// keyed by library id and CLEARED at every Corpus pass: a rebuild is
	// what an epoch drift trip means, so every rebuild recomposes under the
	// CURRENT naming config and a cached namer is never staler than the
	// pass that built it. Guarded by mu — the resolver is consulted by the
	// service's build/reconcile goroutine only, and the lock is the cheap
	// future-proofing a second caller would otherwise re-derive.
	mu     sync.Mutex
	namers map[string]naming.Namer
}

// browseCorpus is one walk's answer: the composed entries, the per-library
// series documents the facet aggregates count, the content watermark, and
// the live id set the orphan sweep sweeps against.
type browseCorpus struct {
	entries   []browse.Entry
	facetDocs map[string][]json.RawMessage
	watermark time.Time
	liveIDs   map[string]bool
}

// stamp advances the corpus watermark to row's updated_at — the max-scan the
// walk folds into its single pass (the watermark is RFC3339Nano UTC TEXT at
// rest; the comparisons run on the parsed times so mixed nano precision can
// never misorder a lexicographic compare).
func (bc *browseCorpus) stamp(row time.Time) {
	if row.After(bc.watermark) {
		bc.watermark = row
	}
}

// epoch reads the naming-config horizon's two-part stamp (see
// browseEpochSQL). A read failure floors to the zero epoch — logged, never
// fatal: a zero stamp differs from any prior one, so the worst case is one
// extra rebuild on the next tick, never a missed one.
func (c *browseComposer) epoch() browse.Epoch {
	var stamp string
	var rows int64
	if err := c.st.DB().QueryRowContext(context.Background(), browseEpochSQL).Scan(&stamp, &rows); err != nil {
		slog.Warn("browse: epoch read failed; drift check floors to rebuild", "error", err)
		return browse.Epoch{}
	}
	return browse.Epoch{UpdatedAt: stamp, Rows: rows}
}

// corpus walks the whole media corpus — the boot build's and every drift
// rebuild's input (browse.Deps.Corpus). Walk failures are log-and-skip per
// library; a whole-walk failure floors to the empty corpus (the honesty
// backstop keeps serving truthful — recall alone degrades until the next
// pass).
func (c *browseComposer) corpus() ([]browse.Entry, map[string][]json.RawMessage, string) {
	out, err := c.walk(context.Background(), time.Time{})
	if err != nil {
		slog.Warn("browse: corpus walk failed; index floors to empty", "error", err)
		return nil, nil, ""
	}
	return out.entries, out.facetDocs, formatStamp(out.watermark)
}

// changed walks the content rows updated after the watermark — the 60 s
// reconcile's incremental path (browse.Deps.Changed). The full corpus scan
// is the walk's implementation, not its cost contract: the FRESH ENTRIES are
// exactly the rows whose updated_at passed the watermark, and the advanced
// watermark is the global max either way. An unparseable watermark (never a
// production state — this wiring minted it) advances nothing and walks
// nothing, logged.
func (c *browseComposer) changed(after string) ([]browse.Entry, string) {
	afterT, err := time.Parse(time.RFC3339Nano, after)
	if err != nil && after != "" {
		slog.Warn("browse: unparseable watermark; walk skipped", "watermark", after, "error", err)
		return nil, after
	}
	out, err := c.walk(context.Background(), afterT)
	if err != nil {
		slog.Warn("browse: incremental walk failed; pass floors", "error", err)
		return nil, after
	}
	return out.entries, formatStamp(out.watermark)
}

// liveIDs reads the corpus's current id set — the orphan sweep's input
// (browse.Deps.LiveIDs). Same walk, same floors.
func (c *browseComposer) liveIDs() map[string]bool {
	out, err := c.walk(context.Background(), time.Time{})
	if err != nil {
		slog.Warn("browse: live-id walk failed; sweep skips", "error", err)
		return nil
	}
	return out.liveIDs
}

// resolver is the About projection bound per library (browse.Deps.Resolver):
// naming.Namer.MetadataFor wrapped with the library's namer — the SAME
// resolver the About block serves (OQ2), so facets can never grow a second
// walk. A namer-build failure (or a vanished library row) resolves nothing:
// the document contributes no facets, the honest absence.
func (c *browseComposer) resolver(libraryID string, raw json.RawMessage) map[string]any {
	n, err := c.namerCached(libraryID)
	if err != nil {
		slog.Warn("browse: resolver namer build failed", "library", libraryID, "error", err)
		return nil
	}
	return n.MetadataFor(raw)
}

// facetDocs reads one library's raw series documents (browse.Deps.FacetDocs)
// — the targeted facet recompute's input. Same walk rule as the corpus:
// tombstoned rows contribute nothing.
func (c *browseComposer) facetDocs(libraryID string) []json.RawMessage {
	id, err := strconv.ParseInt(libraryID, 10, 64)
	if err != nil {
		return nil
	}
	rows, err := c.st.QuerySeries(context.Background(), id, "", access.System())
	if err != nil {
		slog.Warn("browse: facet doc read failed", "library", libraryID, "error", err)
		return nil
	}
	docs := make([]json.RawMessage, 0, len(rows))
	for _, sr := range rows {
		if sr.Status == "deleted" {
			continue
		}
		docs = append(docs, sr.Document)
	}
	return docs
}

// facetIDs resolves ONE library's facet-filter id sets (api Deps.FacetIDs):
// which series ids and item ids carry EVERY supplied facet value, resolved
// through the SAME pass-built resolver the aggregates count with — the
// whole-library scan the design budgets, paid only when a filter is actually
// requested (the handler gates on facets.any()). An unknown value yields an
// empty set (the unknown-value law: 200 empty, never an error); no filter
// supplied is the vacuous conjunct every row carries. Deleted rows match
// nothing — the listing filters them upstream, and a tombstone carries no
// facts.
func (c *browseComposer) facetIDs(ctx context.Context, libraryID int64, genre, kind, status string) (map[string]bool, map[string]bool, error) {
	sids, iids := map[string]bool{}, map[string]bool{}
	lib := strconv.FormatInt(libraryID, 10)
	rows, err := c.st.QuerySeries(ctx, libraryID, "", access.System())
	if err != nil {
		return nil, nil, fmt.Errorf("browse: facet series scan lib %d: %w", libraryID, err)
	}
	for _, sr := range rows {
		if sr.Status == "deleted" {
			continue
		}
		if facetCarries(c.resolver(lib, sr.Document), genre, kind, status) {
			sids[sr.ID] = true
		}
	}
	for offset := 0; ; offset += browseWalkBatch {
		batch, err := c.st.QueryItems(ctx, libraryID, "", "", false, browseWalkBatch, offset, access.System())
		if err != nil {
			return nil, nil, fmt.Errorf("browse: facet item scan lib %d: %w", libraryID, err)
		}
		for _, it := range batch {
			if it.Status == "deleted" {
				continue
			}
			if facetCarries(c.resolver(lib, it.Document), genre, kind, status) {
				iids[it.ID] = true
			}
		}
		if len(batch) < browseWalkBatch {
			break
		}
	}
	return sids, iids, nil
}

// facetCarries reports whether one document's resolved About block carries
// every supplied facet value — the exact reads countLibraryFacets counts
// with, so a value the chips serve is a value the filter matches. The empty
// filter set is vacuously true (every row); a non-carrier document matches
// only it.
func facetCarries(resolved map[string]any, genre, kind, status string) bool {
	if genre == "" && kind == "" && status == "" {
		return true
	}
	about, ok := resolved["about"].(map[string]any)
	if !ok {
		return false
	}
	if genre != "" && !facetGenreCarries(about["genres"], genre) {
		return false
	}
	if kind != "" && facetScalar(about["kind"]) != kind {
		return false
	}
	if status != "" && facetScalar(about["status"]) != status {
		return false
	}
	return true
}

// facetGenreCarries reports whether the resolved genres array carries the
// requested value verbatim (the same usable-value test the counting side
// applies: non-empty strings only).
func facetGenreCarries(v any, genre string) bool {
	arr, ok := v.([]any)
	if !ok {
		return false
	}
	for _, e := range arr {
		if s, is := e.(string); is && s == genre {
			return true
		}
	}
	return false
}

// facetScalar reads one resolved scalar facet value the way the counting
// side does: a non-empty string, else "" (which never matches a requested
// value — the unknown-value law).
func facetScalar(v any) string {
	s, _ := v.(string)
	return s
}

// namerCached returns the library's namer from the per-pass cache, building
// it on a miss. A vanished library row floors to the empty namer — the ONE
// floor every namerFor call site shares api-side — and is NOT cached: the
// row may return.
func (c *browseComposer) namerCached(libraryID string) (naming.Namer, error) {
	c.mu.Lock()
	n, ok := c.namers[libraryID]
	c.mu.Unlock()
	if ok {
		return n, nil
	}
	id, err := strconv.ParseInt(libraryID, 10, 64)
	if err != nil {
		return naming.Namer{}, fmt.Errorf("browse: library id %q: %w", libraryID, err)
	}
	ctx := context.Background()
	lib, err := c.st.GetLibrary(ctx, id, access.System())
	if errors.Is(err, sql.ErrNoRows) {
		return naming.Namer{}, nil
	}
	if err != nil {
		return naming.Namer{}, fmt.Errorf("browse: get library %d: %w", id, err)
	}
	rows, err := c.st.QuerySeries(ctx, id, "", access.System())
	if err != nil {
		return naming.Namer{}, fmt.Errorf("browse: query series lib %d: %w", id, err)
	}
	n, err = c.buildNamer(ctx, lib, rows)
	if err != nil {
		return naming.Namer{}, err
	}
	c.mu.Lock()
	c.namers[libraryID] = n
	c.mu.Unlock()
	return n, nil
}

// buildNamer composes the library's namer — the cmd mirror of the api-side
// namerFor over a library row and its whole-library series read already in
// hand (the walk reads the rows anyway, so nothing pays twice; the ONE
// series read feeds both the join map and the walk). The walk inputs ride
// the SAME ModulePresentation closure api.Deps carries, handed the bare
// ctx: the zero-Viewer floor its chain-mute loop degenerates on — the
// shared/full index is mute-blind by design (D2), per-viewer muting lives
// at serve time.
func (c *browseComposer) buildNamer(ctx context.Context, lib store.Library, rows []store.Series) (naming.Namer, error) {
	var pres api.ModulePresentation
	if c.modulePres != nil {
		p, err := c.modulePres(ctx, lib.ModuleID, lib.ID)
		if err != nil {
			return naming.Namer{}, fmt.Errorf("browse: module presentation lib %d: %w", lib.ID, err)
		}
		pres = p
	}
	tmpl := lib.NamingElementName
	if tmpl == "" {
		tmpl = pres.ItemName
	}
	byPath := make(map[string]store.Series, len(rows))
	for _, sr := range rows {
		byPath[sr.RelativePath] = sr
	}
	return naming.Namer{
		GroupStyle:   lib.NamingGroupStyle,
		ElementTmpl:  tmpl,
		SeriesByPath: byPath,
		TitleSources: pres.TitleSources,
		LangPrefs:    pres.LanguagePreference,
		Chain:        pres.SourceChain,
		ModuleID:     lib.ModuleID,
	}, nil
}

// walk reads the whole media corpus once: per media library, ONE series
// read feeds both the namer's series-by-path join and the walk; items arrive
// paged. after.IsZero() is the corpus shape (every live row); otherwise only
// rows updated after the watermark join the entries — the watermark and the
// live set cover the corpus either way. Tombstoned rows never index, never
// count as facets, and never hold the watermark — a delete's convergence is
// the epoch's count leg (Q3).
func (c *browseComposer) walk(ctx context.Context, after time.Time) (browseCorpus, error) {
	// The per-pass clear the namer cache's own invariant promises: every
	// pass recomposes under the CURRENT naming config, so a cached namer
	// never outlives the pass that walks — an epoch-drift rebuild's facet
	// recompute (and FacetIDs, through the same Resolver) resolves via
	// fresh namers, never the pre-flip ones this map would otherwise hold
	// until restart. Under mu, so the resolver-visible cache flips
	// coherently with the walk that rebuilds it.
	c.mu.Lock()
	c.namers = map[string]naming.Namer{}
	c.mu.Unlock()
	libs, err := c.st.ListLibraries(ctx, access.System())
	if err != nil {
		return browseCorpus{}, fmt.Errorf("browse: list libraries: %w", err)
	}
	out := browseCorpus{
		entries:   make([]browse.Entry, 0),
		facetDocs: map[string][]json.RawMessage{},
		liveIDs:   map[string]bool{},
	}
	// overrides memoizes the per-entity title override across the pass — the
	// corpus is a snapshot, so a row's override read at most once per walk.
	overrides := map[string]string{}
	override := func(entityID string) string {
		if so, ok := overrides[entityID]; ok {
			return so
		}
		so := ""
		row, err := c.st.GetTitleOverride(ctx, entityID)
		switch {
		case err == nil:
			so = row.Title
		case !errors.Is(err, sql.ErrNoRows):
			slog.Warn("browse: title override read failed", "entity", entityID, "error", err)
		}
		overrides[entityID] = so
		return so
	}
	for _, lib := range libs {
		mod, err := c.reg.Get(lib.ModuleID)
		if err != nil {
			slog.Warn("browse: library module unresolvable; library skipped",
				"library", lib.ID, "module", lib.ModuleID, "error", err)
			continue
		}
		if mod.MediaType == "image" {
			continue // photo library — excluded v1 (OQ1)
		}
		rows, err := c.st.QuerySeries(ctx, lib.ID, "", access.System())
		if err != nil {
			slog.Warn("browse: series walk failed; library skipped", "library", lib.ID, "error", err)
			continue
		}
		namer, err := c.buildNamer(ctx, lib, rows)
		if err != nil {
			slog.Warn("browse: namer build failed; library skipped", "library", lib.ID, "error", err)
			continue
		}
		libID := strconv.FormatInt(lib.ID, 10)
		docs := make([]json.RawMessage, 0, len(rows))
		for _, sr := range rows {
			if sr.Status == "deleted" {
				continue
			}
			docs = append(docs, sr.Document)
			out.liveIDs[sr.ID] = true
			out.stamp(sr.UpdatedAt)
			if after.IsZero() || sr.UpdatedAt.After(after) {
				name := namer.SeriesName(sr, override(sr.ID))
				out.entries = append(out.entries, browse.Entry{
					ID:          sr.ID,
					LibraryID:   libID,
					Kind:        browse.KindSeries,
					DisplayName: name,
					Alternates:  servedAlternates(seriesAlternates(namer, sr), name),
				})
			}
		}
		out.facetDocs[libID] = docs
		if err := c.walkItems(ctx, lib, namer, after, override, &out); err != nil {
			slog.Warn("browse: item walk failed; library's items skipped", "library", lib.ID, "error", err)
		}
	}
	return out, nil
}

// walkItems walks one library's items, paged, and appends their entries to
// the corpus under assembly — the same tiers and floors as the series walk.
func (c *browseComposer) walkItems(
	ctx context.Context, lib store.Library, namer naming.Namer,
	after time.Time, override func(string) string, out *browseCorpus,
) error {
	libID := strconv.FormatInt(lib.ID, 10)
	for offset := 0; ; offset += browseWalkBatch {
		batch, err := c.st.QueryItems(ctx, lib.ID, "", "", false, browseWalkBatch, offset, access.System())
		if err != nil {
			return fmt.Errorf("browse: query items lib %d: %w", lib.ID, err)
		}
		for _, it := range batch {
			if it.Status == "deleted" {
				continue
			}
			out.liveIDs[it.ID] = true
			out.stamp(it.UpdatedAt)
			if after.IsZero() || it.UpdatedAt.After(after) {
				name := c.itemName(ctx, namer, it, override)
				out.entries = append(out.entries, browse.Entry{
					ID:          it.ID,
					LibraryID:   libID,
					Kind:        browse.KindItem,
					DisplayName: name,
					Alternates:  servedAlternates(itemAlternates(namer, it), name),
				})
			}
		}
		if len(batch) < browseWalkBatch {
			return nil
		}
	}
}

// itemName composes one item's served name through the same chain the DTO
// seam runs: the item's own override first, the composed element name (whose
// {title} tier is the parent series' name through the series override), the
// walk floor, the _view floor. The parent series' override is point-read
// beside the row — the withSeriesOverride posture, priced per series id.
func (c *browseComposer) itemName(ctx context.Context, namer naming.Namer, it store.Item, override func(string) string) string {
	n := namer
	if sr, _, _, ok := namer.ElementFacts(naming.DocMap(it.Document)); ok {
		n.SeriesOverride = override(sr.ID)
	}
	return n.ItemName(it, override(it.ID))
}

// seriesAlternates lists every name the series' precedence chain COULD have
// served but didn't win: the walk's unpicked titles (every language variant
// of every enabled source's title — "aria" must survive «Ария» winning, D2),
// the parser-title leg, the dir-name floor, the path-segment floor.
func seriesAlternates(n naming.Namer, sr store.Series) []string {
	doc := naming.DocMap(sr.Document)
	out := walkTitles(n, doc)
	if parsed, ok := doc["parsed"].(map[string]any); ok {
		if raw, _ := parsed["dir_name_raw"].(string); raw != "" {
			out = append(out, raw)
		}
	}
	if seg := lastPathSegment(sr.RelativePath); seg != "" {
		out = append(out, seg)
	}
	return out
}

// itemAlternates is seriesAlternates over an item's own chain: the walk's
// unpicked titles, the composed element name (searching the SHOW finds its
// episodes), and the _view.title floor — verbatim, number-valued titles
// included (the SPA's lossless primitive stringify).
func itemAlternates(n naming.Namer, it store.Item) []string {
	doc := naming.DocMap(it.Document)
	out := walkTitles(n, doc)
	if name, ok := n.ElementName(doc); ok {
		out = append(out, name)
	}
	out = append(out, viewTitleFloor(doc))
	return out
}

// walkTitles lists the title-walk candidates a document carries across the
// namer's enabled title sources: a string title verbatim, an object title's
// EVERY language value (the pickLanguage pick is what won; the unpicked
// languages are the alternates). Disabled entries are skipped — a gated-off
// source contributes no match surface (a gate flip converges through the
// epoch, D4).
func walkTitles(n naming.Namer, doc map[string]any) []string {
	var out []string
	sources, _ := doc["sources"].(map[string]any)
	for _, ts := range n.TitleSources {
		if !ts.Enabled {
			continue
		}
		ns, ok := sources[ts.ID].(map[string]any)
		if !ok {
			continue
		}
		switch title := ns["title"].(type) {
		case string:
			if title != "" {
				out = append(out, title)
			}
		case map[string]any:
			for _, v := range title {
				if s, is := v.(string); is && s != "" {
					out = append(out, s)
				}
			}
		}
	}
	// The parser-title leg is below the walk in the precedence chains (the
	// composer floors to it when every walk source floored) — as an
	// alternate it recalls the directory-named row under its parsed title.
	if parser, ok := sources["serial-parser"].(map[string]any); ok {
		if title, _ := parser["title"].(string); title != "" {
			out = append(out, title)
		}
	}
	return out
}

// viewTitleFloor replicates the naming composer's _view.title.value floor —
// the item document's own last tier (the naming original is unexported; the
// lossless number stringify is the SPA's String(value), INV-no-rounding).
func viewTitleFloor(doc map[string]any) string {
	view, ok := doc["_view"].(map[string]any)
	if !ok {
		return ""
	}
	title, ok := view["title"].(map[string]any)
	if !ok {
		return ""
	}
	switch v := title["value"].(type) {
	case string:
		return v
	case json.Number:
		return v.String()
	default:
		return ""
	}
}

// lastPathSegment is the raw last path segment, verbatim (the naming
// composer's floor; replicated because the original is unexported).
func lastPathSegment(relPath string) string {
	if i := strings.LastIndexByte(relPath, '/'); i >= 0 {
		return relPath[i+1:]
	}
	return relPath
}

// servedAlternates dedupes the candidate names and drops the composed
// winner: the entry's Alternates are the LOSING names only — an alternate
// equal to the served name would double-book one entity's match surface.
func servedAlternates(candidates []string, winner string) []string {
	seen := map[string]bool{winner: true}
	out := make([]string, 0, len(candidates))
	for _, c := range candidates {
		if c == "" || seen[c] {
			continue
		}
		seen[c] = true
		out = append(out, c)
	}
	return out
}

// formatStamp renders a watermark the way the store persists updated_at —
// RFC3339Nano UTC TEXT (the PlaybackProgress.UpdatedAt convention), so the
// stamp round-trips through Changed's parse verbatim. The zero time is the
// empty stamp (an empty corpus carries no watermark).
func formatStamp(t time.Time) string {
	if t.IsZero() {
		return ""
	}
	return t.UTC().Format(time.RFC3339Nano)
}
